import json, re
d = json.load(open('object_info.json'))
hits = {}
for k,node in d.items():
    inp = node.get('input',{})
    fields = {}
    for sec in ('required','optional'):
        for name,spec in inp.get(sec,{}).items():
            if isinstance(spec,(list,tuple)):
                typ = spec[0] if spec else '?'
                info = spec[1] if len(spec)>1 else None
            else:
                typ = str(spec)
                info = None
            t = (info.get('tooltip') if isinstance(info,dict) else '') or ''
            if re.search(r'api_key|auth_token|token|URL|endpoint|\bhost\b|base_url|api_base', name+' '+t, re.I):
                fields[name] = typ
    if fields:
        hits[k] = fields
for k,v in sorted(hits.items()):
    print(k, '->', v)
