import json
d = json.load(open('object_info.json'))
# nodes accepting VIDEO input, and all output nodes in comfy_api_nodes
video_consumers = []
output_nodes = []
for k,node in d.items():
    inp = node.get('input',{})
    for sec in ('required','optional'):
        for name,spec in inp.get(sec,{}).items():
            typ = spec[0] if isinstance(spec,(list,tuple)) else str(spec)
            if typ == 'VIDEO':
                video_consumers.append((k,name,sec))
    if node.get('output_node'):
        output_nodes.append((k, node.get('category'), list((node.get('output') or []))))
print('=== VIDEO consumers ===')
for v in video_consumers: print(v)
print('=== output nodes (comfy_api_nodes) ===')
for o in output_nodes:
    if 'api node' in (o[1] or ''): print(o)
print('=== total output nodes:', len(output_nodes))
# also nodes that output VIDEO
print('=== nodes outputting VIDEO ===')
for k,node in d.items():
    if 'VIDEO' in (node.get('output') or []):
        print(k, node.get('output'))
"
